import{_ as e,o as i,c as a,a2 as r}from"./chunks/framework.DgVVaeR-.js";const u=JSON.parse('{"title":"Rust Native コア (pixiv-api) 仕様","description":"UniFFI を用いた Rust API クライアント、バッファサイズ上限制限、メモリ安全設計","frontmatter":{"title":"Rust Native コア (pixiv-api) 仕様","description":"UniFFI を用いた Rust API クライアント、バッファサイズ上限制限、メモリ安全設計"},"headers":[],"relativePath":"dev/rust-core.md","filePath":"dev/rust-core.md","lastUpdated":1791090709000}'),l={name:"dev/rust-core.md"};function o(d,t,s,n,c,p){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="rust-native-コア-pixiv-api-仕様" tabindex="-1">Rust Native コア (<code>pixiv-api</code>) 仕様 <a class="header-anchor" href="#rust-native-コア-pixiv-api-仕様" aria-label="Permalink to &quot;Rust Native コア (`pixiv-api`) 仕様&quot;">​</a></h1><p><code>rust/pixiv-api</code> は、Pixiv API のネットワーク通信およびレスポンス JSON のパース・型検証を行うネイティブ Rust クレートです。</p><hr><h2 id="バッファ上限仕様表" tabindex="-1">バッファ上限仕様表 <a class="header-anchor" href="#バッファ上限仕様表" aria-label="Permalink to &quot;バッファ上限仕様表&quot;">​</a></h2><p><code>pixiv-api</code> 内で規定されている各データの安全読み込み上限サイズです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">対象データ</th><th style="text-align:left;">上限サイズ</th><th style="text-align:left;">超過時の動作</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JSON レスポンス</strong></td><td style="text-align:left;"><strong>16 MiB</strong></td><td style="text-align:left;">デコードストリームバッファ上限。超過時は即時 <code>ApiError</code> を発生</td></tr><tr><td style="text-align:left;"><strong>小説本文 (HTML)</strong></td><td style="text-align:left;"><strong>8 MiB</strong></td><td style="text-align:left;">小説本文パースバッファ上限</td></tr><tr><td style="text-align:left;"><strong>HTTP エラー本文</strong></td><td style="text-align:left;"><strong>64 KiB</strong></td><td style="text-align:left;">サーバーエラーレスポンス取得上限</td></tr><tr><td style="text-align:left;"><strong>HTTPエラー詳細文字列</strong></td><td style="text-align:left;"><strong>4 KiB + 省略記号</strong></td><td style="text-align:left;">HTTPエラーの説明に使用する本文抜粋の上限</td></tr></tbody></table><hr><h2 id="モジュール構造-rust-pixiv-api-src" tabindex="-1">モジュール構造 (<code>rust/pixiv-api/src/</code>) <a class="header-anchor" href="#モジュール構造-rust-pixiv-api-src" aria-label="Permalink to &quot;モジュール構造 (`rust/pixiv-api/src/`)&quot;">​</a></h2><ul><li><code>lib.rs</code>: モジュールと公開APIのエントリポイント</li><li><code>client/</code>: HTTP 通信クライアントおよびヘッダー・認証処理</li><li><code>models/</code>: Domain 別 DTO 定義</li></ul><hr><h2 id="android-abi-出力" tabindex="-1">Android ABI 出力 <a class="header-anchor" href="#android-abi-出力" aria-label="Permalink to &quot;Android ABI 出力&quot;">​</a></h2><ul><li><code>arm64-v8a/libpalleria_pixiv_api.so</code></li><li><code>armeabi-v7a/libpalleria_pixiv_api.so</code></li><li><code>x86_64/libpalleria_pixiv_api.so</code></li></ul><p>上限値の定義は <code>src/client/transport.rs</code> にあります。うごイラのアーカイブ取得には <code>src/client/ugoira_download.rs</code> の512 MiB上限もあります。</p>',13)])])}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
